// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-add-text-to-image' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>写真に文字を入れるのは、数分でできます。画像をアップロードして、言葉を入力し、フォントと色を選んで、文字を属する場所に置くだけです。</p>\n<p>この記事では、作業全体の流れを順番に解説します。1つと複数のレイヤー、フォントとサイズの選択、アウトラインと影、文字をシャープに保つ書き出し設定までカバーします。</p>\n<p>読み終わるころには、写真にキャプションを付けたり、ミームを作ったり、スクリーンショットにラベルを付けたり、SNSグラフィックをデザインしたりできるようになります。結果を確認するまで、元の写真は残しておきましょう。</p>\n<h2 id=\"before-you-start\">始める前に：言葉を計画する</h2>\n<p>ツールを開く前に、文字を書きましょう。あらかじめ決めたキャプションは、編集画面を見ながら考えたものより短くてはっきりします。</p>\n<p>短くしましょう。数語の見出しと1行のキャプションは、写真を隠して見る人を圧倒する段落よりはるかに効果的です。</p>\n<p>雰囲気も決めましょう。太いフォントはミームやセールバナーに合い、軽いセリフは結婚式の写真や引用グラフィックに合います。</p>\n<p><a href=\"/ja/gazou-ni-tekisuto-tsuika/\">画像に文字を追加するツール</a>をブラウザで開きます。処理はすべて端末内で行われるので、写真がサーバーにアップロードされることはありません。</p>\n<h2 id=\"step-by-step\">画像に文字を入れる6つのステップ</h2>\n<p>手順は、キャプションでもミームでもラベルでも同じです。アップロード、入力、スタイル設定、配置、確認、ダウンロードです。</p>\n<p>スタイル設定には時間をかけましょう。フォント、サイズ、色、アウトラインが、文字が読めるか、写真に消えてしまうかを決めます。</p>\n<ol>\n<li>画像をドロップゾーンにドラッグするか、端末から選ぶか、スクリーンショットをCtrl+Vで貼り付けてアップロードします。</li>\n<li>「文字を追加」をクリックし、文字の内容ボックスにキャプションを入力します。Enterで追加の行を作れます。</li>\n<li>フォントを選び、文字サイズを2パーセントから22パーセントの間で設定し、写真とコントラストのある色を選びます。</li>\n<li>背景が忙しい場合は文字のアウトラインやドロップシャドウを付け、レイヤーを所定の場所にドラッグします。</li>\n<li>追加の行にはレイヤーをさらに加え、それぞれを別々に選択して個別にスタイルを設定します。</li>\n<li>保存形式と画質を選んで「ダウンロード」をクリックし、キャプション付きの画像を保存します。</li>\n</ol>\n<p>共有する前に、ダウンロードしたファイルを一度開きましょう。文字がはっきり読め、写真の大切なものが覆われていないか確認します。</p>\n<h2 id=\"adding-your-first-layer\">最初の文字レイヤーを追加する</h2>\n<p>「文字を追加」をクリックすると、最初のレイヤーができます。ツールは画像の上に標準のキャプションを置くので、文字の内容ボックスで自分の言葉に置き換えます。</p>\n<p>表示させたいとおりに、正確に言葉を入力します。画像の上のスペルミスは見逃しにくいので、次に進む前に文字を2回読みましょう。</p>\n<p>レイヤーは、標準では画像の中央に現れます。見出しなら上に、キャプションなら下に、ドラッグして置きたい位置に動かします。</p>\n<p>各レイヤーは独立しています。1つのレイヤーを大きく太いフォントに、もう1つを小さく軽いフォントにでき、2つが互いに影響することはありません。</p>\n<h2 id=\"choosing-a-font\">フォントを選ぶ</h2>\n<p>ツールには、太いサンセリフからクラシックなセリフまで、組み込みフォントのセットがあります。画像とメッセージの雰囲気に合うものを選びましょう。</p>\n<p>ミームやセールバナーには、太いサンセリフを使います。重い文字は小さいサイズでも忙しい背景でも読みやすいままで、ミームにまさに必要なものです。</p>\n<p>引用や結婚式の写真には、セリフやエレガントなフォントを使います。軽い筆致はフォーマルで落ち着いた印象になり、思慮深いメッセージに合います。</p>\n<p>使うサイズでフォントを確認しましょう。大きいサイズでは美しく見える装飾フォントも、小さいサイズでは読めなくなることがあります。</p>\n<h2 id=\"setting-text-size\">文字サイズを設定する</h2>\n<p>文字サイズは、画像の2パーセントから22パーセントまでです。見出しは範囲の上のほうの大きいサイズが必要で、キャプションやクレジット行は小さいサイズで十分です。</p>\n<p>割合指定なら、異なる画像サイズでも文字がそろいます。同じ設定が、小さいサムネイルでも大きなカメラ写真でも正しく見えます。</p>\n<p>共有する寸法でサイズをテストしましょう。フルサイズでは太く見える見出しも、画像がずっと小さく表示されるSNSフィードのプレビューでは小さく見えることがあります。</p>\n<p>レイヤーが2つあるときは、サイズを変えましょう。大きな見出しと小さいキャプションで、はっきりした階層ができ、見る人は何を先に読むべきかわかります。</p>\n<h2 id=\"choosing-a-colour\">文字の色を選ぶ</h2>\n<p>白い文字は暗い背景で、黒い文字は明るい背景で読めますが、ほとんどの写真は両方を含みます。文字を置く実際の場所に合わせて、色を確認しましょう。</p>\n<p>文字は、写真で最も無地の部分に置きましょう。晴れた空や空白の壁の上のキャプションは、忙しい群衆の上のものよりはるかに読みやすいです。</p>\n<p>明るい色は短い見出しには使えますが、長いキャプションでは読みにくいです。強い色は数語だけに使い、残りは白か黒にしましょう。</p>\n<p>どの色も合わないときは、背景パネルを加えましょう。白い文字の後ろの半透明の暗いボックスは、どこでも読めるようにしますが、画像をより多く覆います。</p>\n<h2 id=\"outline-and-shadow\">アウトラインやドロップシャドウを付ける</h2>\n<p>アウトラインは、各文字の周りに縁を描きます。白い文字の周りの細い暗いアウトラインは、明るい空でも読みやすく保ちます。だからミームはアウトラインを使います。</p>\n<p>ドロップシャドウは、文字を背景から持ち上げます。文字の後ろに柔らかい暗い縁を加え、アウトラインのような硬い見た目にならずに目立たせます。</p>\n<p>どちらか一方を使い、両方を最大限に使わないようにしましょう。アウトラインと強い影を組み合わせると、文字がごちゃごちゃに見えます。1つの効果だけならきれいなままです。</p>\n<p>クラシックなミームの文字には、太い暗いアウトラインの白い文字を使います。この組み合わせは、ほぼどんな背景でも読めるので、標準になりました。</p>\n<h2 id=\"moving-layers\">レイヤーを動かして選択する</h2>\n<p>レイヤーをドラッグすると、画像のどこにでも動かせます。レイヤーが複数あるときは、ツールで各レイヤーを別々に選択できるので、ほかのレイヤーに触れずに1つを編集できます。</p>\n<p>フォントやサイズ、色を変える前に、編集したいレイヤーをクリックします。間違ったレイヤーを編集するのはよくある失敗で、どのレイヤーが有効か確認すれば簡単に避けられます。</p>\n<p>上と下は、キャプションの定番の位置です。上の見出しと下のオチはミームの形式で、目が上から下へ読むのでうまくいきます。</p>\n<p>文字は端から離して置きましょう。境界に触れるキャプションは窮屈に見え、サービスは画面サイズごとに端をさらに切り取ることがよくあります。</p>\n<h2 id=\"rotating-text\">文字レイヤーを回転させる</h2>\n<p>文字レイヤーはカスタム角度で傾けられ、デザインにエネルギーを加えます。少し斜めの見出しはダイナミックに感じられ、まっすぐな文字は落ち着いてフォーマルに感じられます。</p>\n<p>回転は控えめに使いましょう。数度の小さな傾きは個性を加えますが、急な角度は文字を読みにくくし、ミスのように見えます。</p>\n<p>斜めの文字は、目を引くためのポスターやSNSグラフィックに適しています。明確さが最も大切な説明やラベルには向きません。</p>\n<p>回転した文字は、表示されるサイズで確認しましょう。フルサイズでは良く見える傾きが、フィードのプレビューでは小さい文字を読めなくすることがあります。</p>\n<h2 id=\"multi-line-captions\">複数行のキャプションとミームのレイアウト</h2>\n<p>文字の内容ボックスの中でEnterを押すと、同じレイヤーに新しい行ができます。余計なレイヤーなしに、2〜3行にわたるキャプションを書けます。</p>\n<p>ミームでは、上のキャプションに1つのレイヤー、下に1つのレイヤーを使います。別のレイヤーなら、各行を属する場所に正確に置けます。</p>\n<p>行は短くしましょう。画像の幅いっぱいに広がるキャプションは読みにくく、被写体を中心にした短い行は追いやすいです。</p>\n<p>行は、文章の自然な区切りで分けましょう。フレーズの真ん中での改行はぎこちなく感じますが、フレーズの間での改行は意図的に感じられます。</p>\n<h2 id=\"making-a-meme\">数分でミームを作る</h2>\n<p>ミームは、短くて面白いキャプションの付いた写真で、たいてい上と下に太い暗いアウトラインの白い文字があります。形式はシンプルで、そのシンプルさがポイントです。</p>\n<p>写真をアップロードし、上の設定用と下のオチ用のレイヤーを加えます。各行は数語に保ち、ジョークがすぐ伝わるようにします。</p>\n<p>太くてがっしりしたフォントに、暗いアウトラインを使います。クラシックなミームの見た目は、ほぼどんな背景でも読みやすいままなので、標準になりました。</p>\n<p>共有するサイズでミームをプレビューしましょう。フルサイズでははっきりしたジョークも、小さいフィードのプレビューでは読めないことがあるので、投稿する前に確認します。</p>\n<h2 id=\"preview-and-export\">プレビューと書き出し</h2>\n<p>ダウンロードする前に、必ずプレビューしましょう。文字がはっきり読めるか、写真の大切なものが覆われていないか、レイヤーが正しい場所にあるか確認します。</p>\n<p>文字入りの写真には、高画質のJPGを選びましょう。文字の端はJPGの圧縮で少し柔らかくなることがあるので、小さいキャプションでは画質を高く保ちます。</p>\n<p>スクリーンショットや文字入りのグラフィックにはPNGを選びましょう。PNGは可逆なので、文字の端がシャープなままで、必要なときに透明度も保てます。</p>\n<p>PNGでは画質スライダーが隠れるのは、PNGが可逆で、調整する画質設定がないからです。正常な動作であって、ツールの問題ではありません。</p>\n<h2 id=\"adding-text-on-mobile\">スマホやタブレットで文字を入れる</h2>\n<p>ツールはタッチ画面でも使えるので、撮ったスマホの上で写真にキャプションを付けられます。ギャラリーからアップロードし、文字を入力して、指でレイヤーを所定の場所にドラッグします。</p>\n<p>スマホのキーボードでの入力は遅いので、ツールを開く前にキャプションを書きましょう。短くて計画されたキャプションは、その場で考えたものより入力しやすいです。</p>\n<p>指でレイヤーをドラッグするのは、マウスより正確ではありません。中央や上、下の部分を目安に使い、配置を確認するためにズームしましょう。</p>\n<p>ダウンロードしたファイルは、いつものダウンロードフォルダに保存されます。そこからチャットやメール、SNSに直接共有できます。</p>\n<h2 id=\"troubleshooting\">よくある文字トラブルの解決法</h2>\n<p>文字が読めないなら、色が背景と同じになっている可能性があります。色を変えるか、アウトラインを付けるか、レイヤーを写真の無地の部分に移しましょう。</p>\n<p>間違ったレイヤーを編集してしまったら、変更したかったレイヤーをクリックしてもう一度試します。ツールはレイヤーを1つずつ選択するので、スタイルを設定する前にどれが有効か確認しましょう。</p>\n<p>レイヤーが動かないなら、まず選択したか確認します。レイヤーは、ドラッグできる前に有効にしなければならず、1回クリックすればたいてい選択できます。</p>\n<p>書き出しのあとに文字がぼやけて見えるなら、JPGの画質設定が低すぎるかもしれません。より高い画質で再書き出しするか、最もシャープな文字の端のためにPNGに切り替えましょう。</p>\n<h2 id=\"quick-tips\">画像の文字をもっと良くするコツ</h2>\n<p>文字は短くしましょう。よく選ばれた数語は画像を強くしますが、写真に詰め込まれた段落は、説明したかったものそのものを隠してしまいます。</p>\n<p>見出しには1つのフォント、キャプションには1つのフォントを、最大で使いましょう。たくさんの書体を混ぜるとごちゃごちゃに見えますが、一貫した組み合わせはデザインをきれいに保ちます。</p>\n<p>表示されるサイズで文字を確認しましょう。フルサイズでは良く見えるキャプションも、SNSフィードのプレビューでは読めないことがあります。</p>\n<p>文字のない元の写真を保存しておきましょう。文字を書き出しに一体化させると、そのファイルからは取り除けないので、元だけがきれいなコピーです。</p>\n<h2 id=\"text-on-presentation-slides\">プレゼンのスライド画像に文字を入れる</h2>\n<p>スライドの背景として使う写真には、たいてい上にタイトルが必要です。文字レイヤーとしてタイトルを加え、部屋の後ろからでも読みやすい大きく太いフォントを使います。</p>\n<p>タイトルは、写真で最も無地の部分に置きましょう。晴れた空や空白の壁の上の見出しは、忙しい群衆の上のものよりはるかに読みやすいです。</p>\n<p>背景が忙しいときは、暗いアウトラインや影を使います。この効果は、文字を写真から少し持ち上げて読めるようにし、下の画像を隠しません。</p>\n<p>スライド画像は高画質のJPGで書き出しましょう。スライドは大きく投影されるので、文字は投影されたときにシャープなままである必要があり、低画質の書き出しは文字を柔らかくします。</p>\n<p>読みやすさのルールは<a href=\"/ja/blog/gazou-no-tekisuto-yomiyasusa-kotsu/\">画像の文字：フォント・コントラスト・読みやすさ</a>、全体像は<a href=\"/ja/blog/gazou-ni-tekisuto-tsuika-gaido/\">画像に文字を入れる方法完全ガイド</a>をご覧ください。キャプションではなく所有権を示したいときは、<a href=\"/ja/gazou-suimaku/\">画像透かしツール</a>を試してみてください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"スマホで写真に文字を入れるにはどうすればいいですか？","answer":"スマホのブラウザで画像に文字を追加するツールを開き、ギャラリーから写真をアップロードして、「文字を追加」をタップします。キャプションを入力し、フォントとサイズを選んで、指でレイヤーを所定の場所にドラッグしてからダウンロードします。"},{"question":"1枚の画像に2つの異なるキャプションを入れられますか？","answer":"はい、入れられます。上のキャプションと下のキャプションのように、それぞれに別のレイヤーを加えます。各レイヤーを個別に選択してスタイルを設定すれば、見出しは大きく太く、キャプションは小さくできます。"},{"question":"ダウンロードしたあとに文字がぼやけて見えるのはなぜですか？","answer":"JPGの画質設定が低すぎて、文字の端が柔らかくなっている可能性があります。より高い画質で再書き出しするか、PNGに切り替えましょう。PNGは可逆で、文字の端をシャープに保ちます。"},{"question":"クラシックなミームを上下の文字で作るには？","answer":"写真をアップロードし、上の行に1つのレイヤー、下の行にもう1つのレイヤーを加えて、太いサンセリフの白い文字に太い暗いアウトラインを使います。各行は数語に保ち、ジョークがすぐ伝わるようにします。"},{"question":"入力したあとに文字を動かせますか？","answer":"はい、動かせます。レイヤーを選択して、画像のどこにでもドラッグできます。ダウンロードする前なら、いつでもレイヤーを動かしたり、サイズを変えたり、色を変えたり、回転させたりできます。画像を書き出すと、文字は一体化して動かせなくなります。"},{"question":"Instagramの投稿で、文字はどれくらいの大きさにすべきですか？","answer":"フルサイズだけでなく、小さいフィードのプレビューでも読めるほど大きくします。見出しは2〜22パーセントの範囲の上のほうのサイズが必要です。書き出した画像を、フィードに表示されるサイズで見て、結果をテストしましょう。"}];
